INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter einer Bitmap?', 2, '[{"text": "Rastergrafik aus Pixeln", "correct": true, "because": "Bitweise Bilddarstellung"}, {"text": "Vektorgrafik", "correct": false, "because": "Anderes Format"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Bitmap?', 3, '[{"text": "Bilddarstellung in Pixeln", "correct": true, "because": "Visuelle Daten"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Systemleistung steigern", "correct": false, "because": "Kein primäres Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einer Bitmap?', 5, '[{"text": "Pixel", "correct": true, "because": "Grundbausteine"}, {"text": "Farbtiefe", "correct": true, "because": "Bits pro Pixel"}, {"text": "Vektoren", "correct": false, "because": "Vektorgrafik"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Bitmap besteht aus Pixeln. b) Sie ist skalierbar ohne Qualitätsverlust.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Skalierung verlustbehaftet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer Bitmap?', 4, '[{"text": "Auflösung", "correct": false, "because": "Pixelanzahl wichtig"}, {"text": "Farbtiefe", "correct": false, "because": "Qualität entscheidend"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Bitmap-Datei eine Farbtiefe von 24 Bit haben kann?', 2, '[{"text": "Ja", "correct": true, "because": "8 Bit pro RGB-Kanal"}, {"text": "Nein", "correct": false, "because": "Häufig genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Dateiformat ist typisch für Bitmaps?', 3, '[{"text": "BMP", "correct": true, "because": "Bitmap-Format"}, {"text": "SVG", "correct": false, "because": "Vektorgrafik"}, {"text": "TXT", "correct": false, "because": "Textdatei"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Struktur einer Bitmap?', 5, '[{"text": "Header", "correct": true, "because": "Metadaten"}, {"text": "Pixel-Daten", "correct": true, "because": "Bildinformation"}, {"text": "Vektorpfade", "correct": false, "because": "Vektorgrafik"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Bitmaps sind speicherintensiv. b) Sie sind für Animationen ungeeignet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Animationen möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer Bitmap unwichtig?', 4, '[{"text": "Pixelanzahl", "correct": false, "because": "Definiert Auflösung"}, {"text": "Farbtiefe", "correct": false, "because": "Qualität"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine Bitmap komprimiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. PNG"}, {"text": "Nein", "correct": false, "because": "Komprimierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine Bitmap für Fachinformatiker?', 4, '[{"text": "Detailgenaue Darstellung", "correct": true, "because": "Pixelgenau"}, {"text": "Einfache Bearbeitung", "correct": true, "because": "Pixelmanipulation"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Bitmaps nur für Fotos sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Grafiken"}, {"text": "Ja", "correct": false, "because": "Vielseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Bitmap?', 3, '[{"text": "Auflösung", "correct": true, "because": "Qualität"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Bitmap hat eine feste Auflösung. b) Sie ist für Vektorgrafiken geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Vektoren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat eine Bitmap?', 5, '[{"text": "Großer Speicherbedarf", "correct": true, "because": "Pixelbasiert"}, {"text": "Qualitätsverlust bei Skalierung", "correct": true, "because": "Keine Vektoren"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei Bitmaps?', 3, '[{"text": "Verarbeitung und Optimierung", "correct": true, "because": "Bilddatenmanagement"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Bitmap transparent sein?', 2, '[{"text": "Ja", "correct": true, "because": "Mit Alpha-Kanal"}, {"text": "Nein", "correct": false, "because": "Unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool könnte ein Fachinformatiker für Bitmaps nutzen?', 4, '[{"text": "GIMP", "correct": true, "because": "Bildbearbeitung"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}, {"text": "Word", "correct": false, "because": "Textverarbeitung"}]');
